append_css.css:
@media (hover:hover) and (pointer:fine){.masthead nav a:hover,.footer a:hover,.quiet-button:hover{text-decoration:underline}.primary:hover{background:#263c29}.text-link:hover{color:var(--orange);border-color:var(--orange)}.demo-row:hover{background:#ece6d8}.demo-row:hover .demo-arrow{border-color:var(--green);color:var(--green)}.round-button:hover,.copy-button:hover{background:var(--soft)}}
:root{--ease-out:cubic-bezier(.23,1,.32,1)}button,a,summary{touch-action:manipulation}button,.primary,.copy-button{-webkit-user-select:none;user-select:none}.copy-button{color:var(--ink);min-height:44px}.page-header>p,.page-header>div>p{max-width:62ch;line-height:1.6}
@media (prefers-reduced-motion:no-preference){:is(.primary,.copy-button,.round-button,.quiet-button,button):active{transform:scale(.97);transition:transform 120ms var(--ease-out)}}
:is(a,button,summary,select,input,textarea):focus-visible{transition:none!important;transform:none!important}
@media(max-width:620px){.masthead{height:64px}.page-header{padding-block:22px 18px}.page-header h1{margin:8px 0 10px;font-size:42px;letter-spacing:-1.5px}.page-header p{font-size:16px}.hero{padding-block:24px 28px}.try-section{padding-block:32px}}

@media (hover:hover) and (pointer:fine){.activity-card h2 a:hover{text-decoration:underline}}
.activity-card{padding:22px 24px}.activity-card h2{font-size:27px;margin:10px 0 10px}.activity-card>p{line-height:1.55}.activity-times{color:var(--muted);border-top:1px solid var(--line);padding-top:12px;margin-bottom:14px}.card-links{margin-top:auto}.guide-source p,.guide-prompt blockquote,.mode-panel ol{max-width:68ch}.route-list li{grid-template-columns:85px 1fr auto}.route-tabs button{font-size:15px}.library-actions .primary{order:-1}
@media(max-width:620px){.library-actions{margin:14px 0 16px;gap:10px}.activity-guide .library-actions>.primary{width:100%}.activity-card{padding:18px}.activity-card h2{font-size:25px}.mode-tabs{padding-bottom:12px}.mode-tabs button{flex:1}.preset-row{margin:14px 0 8px}.route-list li{grid-template-columns:55px 1fr}.route-list li{padding:16px 0}.tune-transport{position:sticky;bottom:0;z-index:5;background:#faf7ef;border-top:1px solid var(--line);margin-inline:-12px;padding:10px 12px calc(10px + env(safe-area-inset-bottom,0px));gap:10px 14px}.tune-transport .primary{flex:1 1 100%}}
@media print{.tune-transport{position:static}}
